import crimson.Native;import java.nio.*;
public class MicroPoseCheck {public static void main(String[]args)throws Exception{float[] source={1,2,3,Float.POSITIVE_INFINITY,Float.POSITIVE_INFINITY,Float.POSITIVE_INFINITY},dest=new float[3],matrix={1,0,0,1,0,1,0,2,0,0,1,3};Native.microTransform(source,dest,matrix);if(dest[0]!=2||dest[1]!=4||dest[2]!=6)throw new Exception("sentinel tail transform");ByteBuffer bones=ByteBuffer.allocate(56).order(ByteOrder.nativeOrder());bones.putInt(1);bones.putInt(-1);for(float f:matrix)bones.putFloat(f);float[] pose=new float[3];if(!Native.microPose(new float[]{1,2,3},pose,bones.array(),null)||pose[2]!=6)throw new Exception("bone pose");bones.putInt(0,2);if(Native.microPose(new float[]{1,2,3},pose,bones.array(),null))throw new Exception("bone count bounds");System.out.println("MICRO_POSE_PASS transform_sentinel_tail pose invalid_bone_bounds");}}
